/**
 * Stage 5e - Lastpos Calculation.
 *
 * OWNER: Person 1.
 * CONTRACT: computes the set of positions of the last symbols of strings
 * generated by the subexpression rooted at `node`.
 *
 * Rules:
 *  - symbol with position i: { i }
 *  - union(A, B): lastpos(A) ∪ lastpos(B)
 *  - concat(A, B): nullable(B) ? (lastpos(A) ∪ lastpos(B)) : lastpos(B)
 *  - star(A): lastpos(A)
 *
 * Invariant: all returned position sets are sorted in ascending order with no duplicates.
 */

import { unionPositions } from './firstpos';
import { calculateNullable } from './nullable';
import type { SyntaxNode } from './types';

/**
 * Computes and sets `lastpos` for `node` and all of its descendants.
 *
 * @param node The syntax tree node to analyze.
 * @returns Sorted, deduplicated position array.
 */
export function calculateLastpos(node: SyntaxNode): number[] {
  switch (node.type) {
    case 'symbol':
      node.lastpos = node.position !== undefined ? [node.position] : [];
      break;

    case 'union': {
      const leftLast = node.left ? calculateLastpos(node.left) : [];
      const rightLast = node.right ? calculateLastpos(node.right) : [];
      node.lastpos = unionPositions(leftLast, rightLast);
      break;
    }

    case 'concat': {
      const leftLast = node.left ? calculateLastpos(node.left) : [];
      const rightLast = node.right ? calculateLastpos(node.right) : [];
      const rightNullable = node.right
        ? (node.right.nullable ?? calculateNullable(node.right))
        : false;

      node.lastpos = rightNullable ? unionPositions(leftLast, rightLast) : [...rightLast];
      break;
    }

    case 'star': {
      const childLast = node.left ? calculateLastpos(node.left) : [];
      node.lastpos = [...childLast];
      break;
    }
  }

  return node.lastpos;
}
